"""Every register of the RP2040 datasheet, ticked if the emulated chip answers it (docs/reference/register-coverage.md is this script's output; do not edit that file by hand).

    pdftotext -layout rp2040-datasheet.pdf rp2040.txt
    python scripts/audit/register_coverage.py rp2040.txt > docs/reference/register-coverage.md

A register is ticked when a read at BASE + offset on a fresh pure-Python chip does not warn "Unimplemented peripheral read" (for a write-only register, which warns when read: when a write of 0 does not warn). That says the register *exists*; it does not say that it *acts*: a
register can be stored and ignored (the feature checklist, docs/reference/feature-coverage.md, says which), and a tick says nothing about its fields. The register-level conformance (reset
values, reserved bits) is `datasheet_conformance.py`. A table shared by several instances (UART0/UART1, "CH0_..." of the DMA) is listed once, as the datasheet header gives it.
"""

import collections
import os
import sys

sys.path.insert(0, os.path.dirname(__file__))
import datasheet_conformance as D  # sets RP2040PY_SKIP_CYTHON before anything imports the chip
import register_status as ST

# the blocks whose registers the conformance tool does not probe (no base address there) - the base is the datasheet's address map (2.2.2)
EXTRA_BASES = {
    "IO_BANK0": 0x40014000,
    "IO_QSPI": 0x40018000,
    "PADS_BANK0": 0x4001C000,
    "PADS_QSPI": 0x40020000,
    "USB": 0x50110000,
    "XIP": 0x14000000,
}
ORDER = [
    "M0PLUS", "SIO", "TIMER", "WATCHDOG", "RTC", "UART", "SPI", "I2C", "ADC", "PWM", "DMA", "PIO", "SSI", "CLOCKS", "PLL", "XOSC", "ROSC", "PSM", "RESETS", "SYSCFG", "SYSINFO",
    "TBMAN", "VREG_AND_CHIP_RESET", "BUSCTRL", "IO_BANK0", "IO_QSPI", "PADS_BANK0", "PADS_QSPI", "USB", "XIP",
]  # fmt: skip


def answers(address: int) -> bool:
    from rp2040py.rp2040 import RP2040

    chip = RP2040()
    warnings: list[str] = []
    chip.logger.warning = lambda _name, message: warnings.append(message)  # type: ignore[method-assign, assignment]
    try:
        chip.read_uint32(address)
    except Exception:  # noqa: BLE001 - a register that raises on a plain read is not one that answers
        return False
    if not warnings:
        return True
    # a write-only register (TIMEHW, UARTICR, a FIFO's push side) warns when read: it exists if a write does not warn
    warnings.clear()
    try:
        chip.write_uint32(address, 0)
    except Exception:  # noqa: BLE001
        return False
    return not warnings


def main(argv: list[str]) -> int:
    registers = D.parse(argv[1])
    bases = {**D.BASES, **EXTRA_BASES}
    by_block: dict[str, list[dict]] = collections.defaultdict(list)
    for register in registers:
        by_block[register["block"]].append(register)
    rows: dict[str, list[tuple[str, str, dict]]] = {}
    for block, items in by_block.items():
        if block not in bases:
            continue
        rows[block] = []
        for r in items:
            offset = int(r["offset"], 16)
            if not answers(bases[block] + offset):
                rows[block].append(("Absent", "", r))
            else:
                status, note = ST.state(block, offset)
                rows[block].append((status, note, r))
    total = sum(len(v) for v in rows.values())
    kinds = ("Acts", "Stub", "Partial", "Unchecked", "Absent")
    count = {k: sum(1 for v in rows.values() for st, _, _ in v if st == k) for k in kinds}
    out = [
        "<!-- GENERATED by scripts/audit/register_coverage.py from the datasheet text and scripts/audit/register_status.py - do not edit by hand; re-run the script. -->",
        "",
        "# Every register of the RP2040 datasheet: what the model does with it",
        "",
        "| Status | Meaning |",
        "|---|---|",
        "| Acts | the block was read against the datasheet and its registers drive behaviour (0098) |",
        "| Stub | the register exists and reads back (or a constant), but nothing acts on it |",
        "| Partial | it acts, except for the fields named in the note |",
        "| Unchecked | the register answers, but its block was never audited, so nobody has verified that it does anything |",
        "| Absent | the register does not answer |",
        "",
        (
            '**This is a curated list, not a measurement.** "Answers" is measured (a read at the register\'s address does not warn "Unimplemented peripheral read"; for a write-only register, a write of 0 does not warn). '
            '"Acts" is curated: it means the block was audited and the register is in none of the stub / partial lists of `scripts/audit/register_status.py`, each entry of which carries its evidence. A stub that nobody has '
            "listed yet shows as Acts; if you find one, add it there and re-run the script. For what each block does and does not do, see [feature-coverage.md](feature-coverage.md). "
            "A table shared by several instances (UART0/UART1, the DMA's per-channel tables) is listed once, as the datasheet gives it."
        ),
        "",
        f"**{total} registers: {count['Acts']} act, {count['Stub']} are stubs, {count['Partial']} partial, {count['Unchecked']} exist but are unchecked, {count['Absent']} are absent.**",
        "",
        "| Block | Registers | Acts | Stub | Partial | Unchecked | Absent |",
        "|---|---|---|---|---|---|---|",
    ]
    for block in ORDER:
        if block in rows:
            v = rows[block]
            cells = " | ".join(str(sum(1 for st, _, _ in v if st == k)) for k in kinds)
            out.append(f"| {block} | {len(v)} | {cells} |")
    for block in ORDER:
        if block not in rows:
            continue
        out += ["", f"## {block}", ""]
        if ST.stub_reason(block):
            out += [f"Stubs in this block: {ST.stub_reason(block)}.", ""]
        out += ["| Offset | Register | Status | Note |", "|---|---|---|---|"]
        for status, note, register in sorted(rows[block], key=lambda t: int(t[2]["offset"], 16)):
            out.append(f"| `{register['offset']}` | {register['name'].replace('|', '/')} | {status} | {note} |")
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
